//! SFTP over SSH (russh): the first storage adapter.
//!
//! - **Server key:** pinned by its SHA-256 fingerprint. On the first connection the fingerprint
//!   is reported (`HostKeyUnknown`) for the user to confirm; afterwards any other key is refused
//!   (`HostKeyChanged`).
//! - **Login:** an Ed25519 key generated by GhulSuite (the user adds the public key to
//!   `~/.ssh/authorized_keys` on the server), or a password.
//! - **Writes are atomic:** temporary file, then rename over the old file.

use std::sync::{Arc, Mutex};

use russh::keys::{HashAlg, PrivateKey, PrivateKeyWithHashAlg};
use russh_sftp::client::SftpSession;
use tokio::io::AsyncWriteExt;
use zeroize::Zeroizing;

use super::remote::{check_path, parent, RemoteEntry, RemoteFs};
use super::{block_on, NetError, NetResult, TIMEOUT};

/// How to log in.
#[derive(Clone)]
pub enum SshAuth {
    /// Private key in OpenSSH format.
    Key(Zeroizing<String>),
    Password(Zeroizing<String>),
}

#[derive(Clone)]
pub struct SftpConfig {
    pub host: String,
    pub port: u16,
    pub user: String,
    pub auth: SshAuth,
    /// Base folder on the server (absolute, or relative to the login folder).
    pub base: String,
    /// Confirmed `SHA256:…` fingerprint of the server key; `None` on the first connection.
    pub host_key: Option<String>,
}

/// Generates an Ed25519 key pair: (private key in OpenSSH format, public key line).
pub fn generate_key(comment: &str) -> NetResult<(Zeroizing<String>, String)> {
    use rand_core::RngCore;
    let mut seed = Zeroizing::new([0u8; 32]);
    rand_core::OsRng.fill_bytes(seed.as_mut());
    let mut key = PrivateKey::from(russh::keys::ssh_key::private::Ed25519Keypair::from_seed(&seed));
    key.set_comment(comment);
    let private =
        key.to_openssh(russh::keys::ssh_key::LineEnding::LF).map_err(|e| NetError::Protocol(e.to_string()))?;
    let public = key.public_key().to_openssh().map_err(|e| NetError::Protocol(e.to_string()))?;
    Ok((Zeroizing::new(private.to_string()), public))
}

/// The public key line of a stored private key.
pub fn public_key_of(private: &str) -> NetResult<String> {
    let key = PrivateKey::from_openssh(private).map_err(|e| NetError::Protocol(e.to_string()))?;
    key.public_key().to_openssh().map_err(|e| NetError::Protocol(e.to_string()))
}

struct Client {
    expected: Option<String>,
    seen: Arc<Mutex<Option<String>>>,
}

impl russh::client::Handler for Client {
    type Error = russh::Error;

    async fn check_server_key(&mut self, key: &russh::keys::PublicKeyOrCertificate) -> Result<bool, Self::Error> {
        // Own servers are trusted by their pinned key; host certificates are not used.
        let russh::keys::PublicKeyOrCertificate::PublicKey { key, .. } = key else { return Ok(false) };
        let fp = key.fingerprint(HashAlg::Sha256).to_string();
        *self.seen.lock().unwrap_or_else(|p| p.into_inner()) = Some(fp.clone());
        Ok(self.expected.as_deref() == Some(fp.as_str()))
    }
}

/// An open SFTP connection. Dropping it closes the connection.
pub struct SftpFs {
    sftp: SftpSession,
    _session: russh::client::Handle<Client>,
    base: String,
}

impl SftpFs {
    /// Connects and logs in. The server key must match `config.host_key`.
    pub fn connect(config: &SftpConfig) -> NetResult<SftpFs> {
        let config = config.clone();
        block_on(
            async move {
                let seen = Arc::new(Mutex::new(None));
                let handler = Client { expected: config.host_key.clone(), seen: seen.clone() };
                let ssh_config = Arc::new(russh::client::Config {
                    inactivity_timeout: Some(std::time::Duration::from_secs(120)),
                    ..Default::default()
                });
                let mut session =
                    match russh::client::connect(ssh_config, (config.host.as_str(), config.port), handler).await {
                        Ok(s) => s,
                        Err(e) => {
                            let fp = seen.lock().unwrap_or_else(|p| p.into_inner()).clone();
                            return Err(match (fp, &config.host_key) {
                                (Some(fp), None) => NetError::HostKeyUnknown(fp),
                                (Some(fp), Some(exp)) if &fp != exp => NetError::HostKeyChanged(fp),
                                _ => NetError::Connect(e.to_string()),
                            });
                        }
                    };
                let ok = match &config.auth {
                    SshAuth::Password(p) => session.authenticate_password(&config.user, p.as_str()).await,
                    SshAuth::Key(k) => {
                        let key =
                            PrivateKey::from_openssh(k.as_str()).map_err(|e| NetError::Protocol(e.to_string()))?;
                        session
                            .authenticate_publickey(&config.user, PrivateKeyWithHashAlg::new(Arc::new(key), None))
                            .await
                    }
                }
                .map_err(|e| NetError::Connect(e.to_string()))?;
                if !ok.success() {
                    return Err(NetError::AuthFailed);
                }
                let channel = session.channel_open_session().await.map_err(|e| NetError::Connect(e.to_string()))?;
                channel.request_subsystem(true, "sftp").await.map_err(|e| NetError::Connect(e.to_string()))?;
                let sftp =
                    SftpSession::new(channel.into_stream()).await.map_err(|e| NetError::Protocol(e.to_string()))?;
                sftp.set_timeout(TIMEOUT.as_secs());
                let base = config.base.trim_end_matches('/').to_owned();
                Ok(SftpFs { sftp, _session: session, base })
            },
            TIMEOUT,
        )
    }

    fn full(&self, path: &str) -> NetResult<String> {
        check_path(path)?;
        Ok(match (self.base.is_empty(), path.is_empty()) {
            (true, true) => ".".to_owned(),
            (true, false) => path.to_owned(),
            (false, true) => self.base.clone(),
            (false, false) => format!("{}/{}", self.base, path),
        })
    }
}

impl SftpFs {
    /// Absolute path of `path` on the server (e.g. `/home/max/ghulsuite`).
    pub fn absolute(&self, path: &str) -> NetResult<String> {
        let full = self.full(path)?;
        block_on(async { self.sftp.canonicalize(full).await.map_err(proto) }, TIMEOUT)
    }

    /// Appends `line` to a text file (created with mode 600), without rewriting what is there.
    /// Used for `~/.ssh/authorized_keys`, where losing existing lines must be impossible.
    pub fn append_line(&self, path: &str, line: &str) -> NetResult<()> {
        self.mkdir_all(parent(path))?;
        let full = self.full(path)?;
        let existing = self.read(path)?.unwrap_or_default();
        let mut text = String::new();
        if !existing.is_empty() && !existing.ends_with(b"\n") {
            text.push('\n');
        }
        text.push_str(line.trim_end());
        text.push('\n');
        block_on(
            async {
                use russh_sftp::protocol::{FileAttributes, OpenFlags};
                let mut attrs = FileAttributes::empty();
                attrs.permissions = Some(0o600);
                let mut f = self
                    .sftp
                    .open_with_flags_and_attributes(
                        full,
                        OpenFlags::CREATE | OpenFlags::APPEND | OpenFlags::WRITE,
                        attrs,
                    )
                    .await
                    .map_err(proto)?;
                f.write_all(text.as_bytes()).await.map_err(|e| NetError::Protocol(e.to_string()))?;
                f.shutdown().await.map_err(|e| NetError::Protocol(e.to_string()))
            },
            TIMEOUT,
        )
    }
}

fn proto(e: russh_sftp::client::error::Error) -> NetError {
    NetError::Protocol(e.to_string())
}

fn is_missing(e: &russh_sftp::client::error::Error) -> bool {
    matches!(e, russh_sftp::client::error::Error::Status(s) if s.status_code == russh_sftp::protocol::StatusCode::NoSuchFile)
}

/// Large transfers get more time than single requests.
fn limit_for(len: usize) -> std::time::Duration {
    TIMEOUT + std::time::Duration::from_secs((len / (256 * 1024)) as u64)
}

impl RemoteFs for SftpFs {
    fn list(&self, dir: &str) -> NetResult<Vec<RemoteEntry>> {
        let full = self.full(dir)?;
        block_on(
            async {
                let entries = match self.sftp.read_dir(full).await {
                    Ok(e) => e,
                    Err(e) if is_missing(&e) => return Ok(Vec::new()),
                    Err(e) => return Err(proto(e)),
                };
                let mut out: Vec<RemoteEntry> = entries
                    .map(|e| {
                        let m = e.metadata();
                        RemoteEntry { name: e.file_name(), is_dir: m.is_dir(), size: m.size.unwrap_or(0) }
                    })
                    .filter(|e| e.name != "." && e.name != "..")
                    .collect();
                out.sort_by(|a, b| a.name.cmp(&b.name));
                Ok(out)
            },
            TIMEOUT,
        )
    }

    fn read(&self, path: &str) -> NetResult<Option<Vec<u8>>> {
        let full = self.full(path)?;
        block_on(
            async {
                match self.sftp.read(full).await {
                    Ok(d) => Ok(Some(d)),
                    Err(e) if is_missing(&e) => Ok(None),
                    Err(e) => Err(proto(e)),
                }
            },
            TIMEOUT * 20,
        )
    }

    fn write(&self, path: &str, data: &[u8]) -> NetResult<()> {
        self.mkdir_all(parent(path))?;
        let full = self.full(path)?;
        let tmp = format!("{full}.ghltmp");
        block_on(
            async {
                let mut f = self.sftp.create(tmp.clone()).await.map_err(proto)?;
                f.write_all(data).await.map_err(|e| NetError::Protocol(e.to_string()))?;
                f.shutdown().await.map_err(|e| NetError::Protocol(e.to_string()))?;
                drop(f);
                // SFTP v3 rename does not replace: remove the old file first.
                match self.sftp.remove_file(full.clone()).await {
                    Ok(()) => {}
                    Err(e) if is_missing(&e) => {}
                    Err(e) => return Err(proto(e)),
                }
                self.sftp.rename(tmp, full).await.map_err(proto)
            },
            limit_for(data.len()),
        )
    }

    fn delete(&self, path: &str) -> NetResult<()> {
        let full = self.full(path)?;
        block_on(
            async {
                match self.sftp.remove_file(full).await {
                    Ok(()) => Ok(()),
                    Err(e) if is_missing(&e) => Ok(()),
                    Err(e) => Err(proto(e)),
                }
            },
            TIMEOUT,
        )
    }

    fn mkdir_all(&self, dir: &str) -> NetResult<()> {
        check_path(dir)?;
        if dir.is_empty() && self.base.is_empty() {
            return Ok(());
        }
        // Every folder from the top of the base down to `dir`, so nested new folders work too.
        let absolute = self.base.starts_with('/');
        let mut path = String::new();
        let mut todo: Vec<String> = Vec::new();
        for p in self.base.split('/').chain(dir.split('/')).filter(|p| !p.is_empty()) {
            path = if path.is_empty() && !absolute { p.to_owned() } else { format!("{path}/{p}") };
            todo.push(path.clone());
        }
        block_on(
            async {
                for p in todo {
                    if !self.sftp.try_exists(p.clone()).await.map_err(proto)? {
                        self.sftp.create_dir(p).await.map_err(proto)?;
                    }
                }
                Ok(())
            },
            TIMEOUT,
        )
    }
}
